def _context(root: Path, gse: str, gsms: set[str], *, sample_metadata=None, manifest=None, report=None) -> AdapterContext:
    schema = json.loads((Path(__file__).resolve().parents[1] / "data/anndata_schema.json").read_text())
    return AdapterContext(gse, root, gsms, sample_metadata or {}, manifest or {"files": []},
                          report or {}, schema, "schema-hash")


def _tar_member(path: Path, name: str, payload: bytes, mode: str = "w") -> None:
    with tarfile.open(path, mode) as archive:
        info = tarfile.TarInfo(name)
        info.size = len(payload)
        archive.addfile(info, io.BytesIO(payload))


def _case_tenx_mtx(root: Path):
    root.mkdir()
    prefix = "GSM123_ABC1"
    matrix = sparse.coo_matrix(np.array([[1, 0], [2, 3]], dtype=np.int32))
    with (root / f"{prefix}_matrix.mtx").open("wb") as stream:
        scipy_io.mmwrite(stream, matrix)
    (root / f"{prefix}_barcodes.tsv").write_text("AA-1\nBB-1\n")
    (root / f"{prefix}_features.tsv").write_text("ENSG1\tGene A\tGene Expression\nENSG2\tGene B\tGene Expression\n")
    context = _context(root, "GSE12345", {"GSM123"},
                       sample_metadata={"GSM123": {"patient_id": "P1", "organism": "Homo sapiens", "tissue": "colon", "disease": "UC"}},
                       manifest={"files": [{"filename": f"{prefix}_matrix.mtx", "sha256": "source-hash"}]},
                       report={"10x_candidate_groups": [{"complete_standard_10x_triplet": True}]})
    return TENX_MTX.load(context, TENX_MTX.discover(context)[0])


