def _case_nested(root: Path):
    root.mkdir()
    inner = io.BytesIO()
    with tarfile.open(fileobj=inner, mode="w:gz") as archive:
        entries = {
            "nested/matrix.mtx.gz": gzip.compress(b"%%MatrixMarket matrix coordinate integer general\n2 2 3\n1 1 1\n2 1 2\n2 2 3\n"),
            "nested/barcodes.tsv.gz": gzip.compress(b"AA-1\nBB-1\n"),
            "nested/features.tsv.gz": gzip.compress(b"ENSG1\tGene A\tGene Expression\nENSG2\tGene B\tGene Expression\n"),
        }
        for name, data in entries.items():
            info = tarfile.TarInfo(name)
            info.size = len(data)
            archive.addfile(info, io.BytesIO(data))
    outer = root / "GSM123_RAW.tar.gz"
    _tar_member(outer, "GSM123_nested.tgz", inner.getvalue(), mode="w:gz")
    context = _context(root, "GSE12345", {"GSM123"},
                       sample_metadata={"GSM123": {"patient_id": "P1", "organism": "Homo sapiens", "tissue": "colon", "disease": "UC"}},
                       manifest={"files": [{"filename": outer.name, "sha256": "source-hash"}],
                                 "stored_dataset_qualification": {"modality": "scRNA-seq"}})
    return NESTED_TAR.load(context, NESTED_TAR.discover(context)[0])


def _case_tenx_hdf5(root: Path):
    root.mkdir()
    source = root / "GSM123_matrix.h5"
    with h5py.File(source, "w") as handle:
        matrix = handle.create_group("matrix")
        matrix.create_dataset("data", data=np.asarray([1, 2, 3], dtype=np.int32))
        matrix.create_dataset("indices", data=np.asarray([0, 1, 1], dtype=np.int32))
        matrix.create_dataset("indptr", data=np.asarray([0, 2, 3], dtype=np.int32))
        matrix.create_dataset("shape", data=np.asarray((2, 2), dtype=np.int64))
        matrix.create_dataset("barcodes", data=np.asarray([b"AA-1", b"BB-1"]))
        features = matrix.create_group("features")
        features.create_dataset("name", data=np.asarray([b"Gene A", b"Gene B"]))
        features.create_dataset("feature_type", data=np.asarray([b"Gene Expression"] * 2))
        features.create_dataset("id", data=np.asarray([b"ENSG1", b"ENSG2"]))
    context = _context(root, "GSE12345", {"GSM123"},
                       sample_metadata={"GSM123": {"patient_id": "P1", "organism": "Homo sapiens", "tissue": "colon", "disease": "UC"}},
                       manifest={"files": [{"filename": source.name, "sha256": "source-hash"}]})
    return TENX_HDF5.load(context, TENX_HDF5.discover(context)[0])


def _case_h5ad(root: Path):
    root.mkdir()
    obs = pd.DataFrame(index=pd.Index(["cell-a", "cell-b"], name=None))
    var = pd.DataFrame({"feature_name": ["Gene A", "Gene B"], "feature_type": ["RNA", "RNA"]},
                       index=pd.Index(["ENSG1", "ENSG2"], name="feature_id"))
    source = ad.AnnData(X=sparse.csr_matrix(np.asarray([[1, 0], [0, 2]], dtype=np.int32)), obs=obs, var=var)
    source.layers["source_counts"] = source.X.copy()
    path = root / "GSM123_source.h5ad"
    source.write_h5ad(path)
    context = _context(root, "GSE12345", {"GSM123"}, manifest={"files": [{"filename": path.name, "sha256": "source-hash"}]})
    return H5AD.load(context, H5AD.discover(context)[0])


