def _digest_array(array: np.ndarray) -> str:
    return hashlib.md5(np.asarray(array).tobytes()).hexdigest()


def _json_safe(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): _json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(item) for item in value]
    if isinstance(value, np.ndarray):
        return [_json_safe(item) for item in value.tolist()]
    if isinstance(value, np.generic):
        return _json_safe(value.item())
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    try:
        json.dumps(value)
    except (TypeError, ValueError):
        return repr(value)
    return value


def _frame_signature(frame: pd.DataFrame) -> dict[str, Any]:
    return {"columns": [[str(column), str(frame[column].dtype)] for column in frame.columns],
            "index": frame.index.tolist()}


def _fingerprint(adata: ad.AnnData) -> dict[str, Any]:
    matrix = adata.X.tocsr()
    layers = {}
    for name in sorted((key for key in adata.layers if key is not None), key=str):
        layer = adata.layers[name].tocsr()
        layers[str(name)] = {"data": _digest_array(layer.data), "indices": _digest_array(layer.indices),
                             "indptr": _digest_array(layer.indptr)}
    return {"shape": list(adata.shape),
            "X": {"data": _digest_array(matrix.data), "indices": _digest_array(matrix.indices),
                  "indptr": _digest_array(matrix.indptr)},
            "obs": _frame_signature(adata.obs), "var": _frame_signature(adata.var),
            "uns": {str(key): _json_safe(adata.uns[key]) for key in sorted(adata.uns)},
            "layers": layers}


def actual_fingerprints() -> dict[str, dict[str, Any]]:
    cases = {"tenx_matrix_market": _case_tenx_mtx,
             "dense_dge_tar_GSE150115": _case_dense_dge_150115,
             "dense_dge_tar_GSE162335": _case_dense_dge_162335,
             "nested_tar_expression": _case_nested,
             "tenx_hdf5": _case_tenx_hdf5,
             "h5ad_passthrough": _case_h5ad,
             "dense_gene_cell": _case_dense_gene_cell}
    results = {}
    root = Path(__file__).resolve().parents[1] / ".pt3" / "adapter-parity"
    if root.exists():
        shutil.rmtree(root)
    root.mkdir(parents=True)
    for name, build in cases.items():
        results[name] = _fingerprint(build(root / name))
    return results


def test_shared_adapter_behavior_fingerprints() -> None:
    assert actual_fingerprints() == EXPECTED
